PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS promoters(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS clients(id INTEGER PRIMARY KEY,full_name TEXT NOT NULL,phone TEXT,notes TEXT);
CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY,promoter_id INTEGER REFERENCES promoters(id),name TEXT NOT NULL,UNIQUE(promoter_id,name));
CREATE TABLE IF NOT EXISTS cheques(id INTEGER PRIMARY KEY,cheque_number TEXT NOT NULL,bank_name TEXT,drawer_name TEXT,received_date TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),status TEXT NOT NULL DEFAULT 'received' CHECK(status IN('received','deposited','pending','collected','rejected','returned','cancelled')));
CREATE TABLE IF NOT EXISTS bank_statement_entries(id INTEGER PRIMARY KEY,statement_reference TEXT NOT NULL,statement_date TEXT NOT NULL,entry_date TEXT NOT NULL,bank_transaction_reference TEXT,credit_minor INTEGER NOT NULL DEFAULT 0 CHECK(credit_minor>=0),debit_minor INTEGER NOT NULL DEFAULT 0 CHECK(debit_minor>=0),CHECK((credit_minor>0 AND debit_minor=0) OR (debit_minor>0 AND credit_minor=0)));
CREATE TABLE IF NOT EXISTS collections(id INTEGER PRIMARY KEY,bank_entry_id INTEGER NOT NULL REFERENCES bank_statement_entries(id),collection_date TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0));
CREATE TABLE IF NOT EXISTS allocations(id INTEGER PRIMARY KEY,collection_id INTEGER NOT NULL REFERENCES collections(id),promoter_id INTEGER NOT NULL REFERENCES promoters(id),client_id INTEGER NOT NULL REFERENCES clients(id),project_id INTEGER REFERENCES projects(id),allocation_date TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0));
CREATE TABLE IF NOT EXISTS freezes(id INTEGER PRIMARY KEY,allocation_id INTEGER NOT NULL REFERENCES allocations(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),reason TEXT NOT NULL,frozen_at TEXT NOT NULL,released_at TEXT,release_note TEXT);
CREATE TABLE IF NOT EXISTS outgoing_payments(id INTEGER PRIMARY KEY,payment_reference TEXT NOT NULL UNIQUE,payment_type TEXT NOT NULL CHECK(payment_type IN('periodic','exceptional')),promoter_id INTEGER NOT NULL REFERENCES promoters(id),preparation_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'prepared' CHECK(status IN('prepared','reserved','executed','cancelled')),execution_date TEXT);
CREATE TABLE IF NOT EXISTS payment_details(id INTEGER PRIMARY KEY,payment_id INTEGER NOT NULL REFERENCES outgoing_payments(id),allocation_id INTEGER NOT NULL REFERENCES allocations(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),UNIQUE(payment_id,allocation_id));
CREATE TABLE IF NOT EXISTS treasury_ledger(id INTEGER PRIMARY KEY,movement_type TEXT NOT NULL,collection_id INTEGER REFERENCES collections(id),payment_id INTEGER REFERENCES outgoing_payments(id),movement_date TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),direction TEXT NOT NULL CHECK(direction IN('in','out')));
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY,entity_type TEXT NOT NULL,entity_id INTEGER NOT NULL,action TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TRIGGER IF NOT EXISTS collection_ledger AFTER INSERT ON collections BEGIN INSERT INTO treasury_ledger(movement_type,collection_id,movement_date,amount_minor,direction) VALUES('collection',NEW.id,NEW.collection_date,NEW.amount_minor,'in'); END;
CREATE TRIGGER IF NOT EXISTS allocation_limit BEFORE INSERT ON allocations BEGIN SELECT CASE WHEN (SELECT COALESCE(SUM(amount_minor),0) FROM allocations WHERE collection_id=NEW.collection_id)+NEW.amount_minor>(SELECT amount_minor FROM collections WHERE id=NEW.collection_id) THEN RAISE(ABORT,'allocation exceeds collection') END; END;
CREATE TRIGGER IF NOT EXISTS freeze_limit BEFORE INSERT ON freezes WHEN NEW.released_at IS NULL BEGIN SELECT CASE WHEN (SELECT COALESCE(SUM(amount_minor),0) FROM freezes WHERE allocation_id=NEW.allocation_id AND released_at IS NULL)+NEW.amount_minor>(SELECT amount_minor FROM allocations WHERE id=NEW.allocation_id) THEN RAISE(ABORT,'freeze exceeds allocation') END; END;
CREATE TRIGGER IF NOT EXISTS payment_ledger AFTER UPDATE OF status ON outgoing_payments WHEN NEW.status='executed' AND OLD.status<>'executed' BEGIN INSERT INTO treasury_ledger(movement_type,payment_id,movement_date,amount_minor,direction) SELECT 'payment',NEW.id,NEW.execution_date,SUM(amount_minor),'out' FROM payment_details WHERE payment_id=NEW.id; END;
